import{_ as e,c as t,a2 as r,o}from"./chunks/framework.C_CzCF4k.js";const i="/assets/image-20260614093855936.png",u=JSON.parse('{"title":"2 理论","titleTemplate":"输入法理论与实践","description":"","frontmatter":{"title":"2 理论","titleTemplate":"输入法理论与实践","typora-root-url":"..\\\\..\\\\public"},"headers":[],"relativePath":"book/chapter2/index.md","filePath":"book/chapter2/index.md"}'),l={name:"book/chapter2/index.md"};function h(n,a,d,s,c,_){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_2-理论" tabindex="-1">2 理论 <a class="header-anchor" href="#_2-理论" aria-label="Permalink to &quot;2 理论&quot;">​</a></h1><h2 id="_2-1-模型" tabindex="-1">2.1 模型 <a class="header-anchor" href="#_2-1-模型" aria-label="Permalink to &quot;2.1 模型&quot;">​</a></h2><p>陈一凡等的《汉字键盘输入技术与理论基础》一书对输入模型做了相当深入的研究[3]。他们分析了汉字键盘输入流程，提出了“理想的汉字特征信息键盘输入的数学模型”和“实际的汉字特征信息键盘输入的数学模型” 。他们的数学模型以集合论为工具，说明了汉字、汉字特征信息、键元、汉字内码之间的映射关系及重码的处理办法。</p><p>张侃等按照人的视听感觉、认知和动作对整个汉字键盘输入过程进行分界和说明，得到了一个汉字键盘输入的认知模型[11]。该模型的三个不同层次的加工过程和容量限制分别为评测汉字输入方法的三个主要素质提供理论依据：即长期记忆量与易学性，短期记忆量与心理负荷和易学性，认知、动作加工与易用性和输入速度。</p><p>戴石麟提出了一个基于信息论的输入系统模型[8]，但是在分析和解释时还不太令人满意，有些简单、粗糙。本书对这个模型进一步完善，进行更全面的论述，赋予模型更深刻的含意。完善后的模型如下图所示：</p><p><img src="'+i+'" alt="image-20260614093855936" loading="lazy"></p><h2 id="_2-2-信源" tabindex="-1">2.2 信源 <a class="header-anchor" href="#_2-2-信源" aria-label="Permalink to &quot;2.2 信源&quot;">​</a></h2><h2 id="_2-3-编码" tabindex="-1">2.3 编码 <a class="header-anchor" href="#_2-3-编码" aria-label="Permalink to &quot;2.3 编码&quot;">​</a></h2><h2 id="_2-4-信道" tabindex="-1">2.4 信道 <a class="header-anchor" href="#_2-4-信道" aria-label="Permalink to &quot;2.4 信道&quot;">​</a></h2><h2 id="_2-5-解码" tabindex="-1">2.5 解码 <a class="header-anchor" href="#_2-5-解码" aria-label="Permalink to &quot;2.5 解码&quot;">​</a></h2><h2 id="_2-6-信宿" tabindex="-1">2.6 信宿 <a class="header-anchor" href="#_2-6-信宿" aria-label="Permalink to &quot;2.6 信宿&quot;">​</a></h2><h2 id="_2-7-反馈" tabindex="-1">2.7 反馈 <a class="header-anchor" href="#_2-7-反馈" aria-label="Permalink to &quot;2.7 反馈&quot;">​</a></h2><h2 id="_2-8-噪声" tabindex="-1">2.8 噪声 <a class="header-anchor" href="#_2-8-噪声" aria-label="Permalink to &quot;2.8 噪声&quot;">​</a></h2>',13)])])}const m=e(l,[["render",h]]);export{u as __pageData,m as default};
